import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"35、【晋】 坤下离上","description":"横渠易说 - 35、【晋】 坤下离上","frontmatter":{"title":"35、【晋】 坤下离上","description":"横渠易说 - 35、【晋】 坤下离上"},"headers":[],"relativePath":"zh/classics/hengqu/037.md","filePath":"zh/classics/hengqu/037.md"}'),l={name:"zh/classics/hengqu/037.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_35、【晋】-坤下离上" tabindex="-1">35、【晋】 坤下离上 <a class="header-anchor" href="#_35、【晋】-坤下离上" aria-label="Permalink to “35、【晋】 坤下离上”">​</a></h1><h3 id="彖曰-晋-进也。明出地上-顺而丽乎大明-柔进而上行-是以康侯用锡马蕃庶-画日三接也。" tabindex="-1">彖曰：晋，进也。明出地上，顺而丽乎大明，柔进而上行，是以康侯用锡马蕃庶，画日三接也。 <a class="header-anchor" href="#彖曰-晋-进也。明出地上-顺而丽乎大明-柔进而上行-是以康侯用锡马蕃庶-画日三接也。" aria-label="Permalink to “彖曰：晋，进也。明出地上，顺而丽乎大明，柔进而上行，是以康侯用锡马蕃庶，画日三接也。”">​</a></h3><h3 id="象曰-明出地上-晋-君子以自昭明德。" tabindex="-1">象曰：明出地上，晋，君子以自昭明德。 <a class="header-anchor" href="#象曰-明出地上-晋-君子以自昭明德。" aria-label="Permalink to “象曰：明出地上，晋，君子以自昭明德。”">​</a></h3><h3 id="初六-晋如摧如-贞吉罔孚-裕无咎。-象曰-晋如摧如-独行正也。-裕无咎-未受命也。" tabindex="-1">初六，晋如摧如，贞吉罔孚，裕无咎。 象曰：“晋如摧如”，独行正也。“裕无咎”，未受命也。 <a class="header-anchor" href="#初六-晋如摧如-贞吉罔孚-裕无咎。-象曰-晋如摧如-独行正也。-裕无咎-未受命也。" aria-label="Permalink to “初六，晋如摧如，贞吉罔孚，裕无咎。 象曰：“晋如摧如”，独行正也。“裕无咎”，未受命也。”">​</a></h3><p>居晋之初，正必见摧，故摧如不害于贞吉也。未孚于人，或未见听，宽以居之乃无咎。然初六有应在四，居下援上，未安其分，故曰“未受命”也。</p><h3 id="六二-晋如愁如-贞吉。受兹介福-于其王母。-象曰-受兹介福-以中正也。" tabindex="-1">六二，晋如愁如，贞吉。受兹介福，于其王母。 象曰：“受兹介福”，以中正也。 <a class="header-anchor" href="#六二-晋如愁如-贞吉。受兹介福-于其王母。-象曰-受兹介福-以中正也。" aria-label="Permalink to “六二，晋如愁如，贞吉。受兹介福，于其王母。 象曰：“受兹介福”，以中正也。”">​</a></h3><p>进而无挠，多失于肆，故愁如乃吉。六五以阴居尊，故称“王母”，俱以柔中，故受福可必也。</p><h3 id="六三-众允-悔亡。-象曰-众允之志-上行也。" tabindex="-1">六三，众允，悔亡。 象曰：众允之志，上行也。 <a class="header-anchor" href="#六三-众允-悔亡。-象曰-众允之志-上行也。" aria-label="Permalink to “六三，众允，悔亡。 象曰：众允之志，上行也。”">​</a></h3><p>上历九四，不为众信，则取悔可必，若志应在上，晋为众允，则悔亡。</p><h3 id="九四-晋如鼫鼠-贞厉。-象曰-鼫鼠贞厉-位不当也。" tabindex="-1">九四，晋如鼫鼠，贞厉。 象曰：“鼫鼠贞厉”，位不当也。 <a class="header-anchor" href="#九四-晋如鼫鼠-贞厉。-象曰-鼫鼠贞厉-位不当也。" aria-label="Permalink to “九四，晋如鼫鼠，贞厉。 象曰：“鼫鼠贞厉”，位不当也。”">​</a></h3><p>鼫鼠为物，贪而畏人，体阳在进，反据阴位，故动止皆失，与六三之义为相反矣。</p><h3 id="六五-悔亡-失得勿恤。往吉-无不利。-象曰-失得勿恤-往有庆也。" tabindex="-1">六五，悔亡，失得勿恤。往吉，无不利。 象曰：“失得勿恤”，往有庆也。 <a class="header-anchor" href="#六五-悔亡-失得勿恤。往吉-无不利。-象曰-失得勿恤-往有庆也。" aria-label="Permalink to “六五，悔亡，失得勿恤。往吉，无不利。 象曰：“失得勿恤”，往有庆也。”">​</a></h3><p>进而遇阳，故失得不恤而吉也。位不当必有悔，获吉则悔亡。</p><h3 id="上九-晋其角-维用伐邑-厉吉无咎-贞吝。-象曰-维用伐邑-道未光也。" tabindex="-1">上九，晋其角，维用伐邑，厉吉无咎，贞吝。 象曰：“维用伐邑”，道未光也。 <a class="header-anchor" href="#上九-晋其角-维用伐邑-厉吉无咎-贞吝。-象曰-维用伐邑-道未光也。" aria-label="Permalink to “上九，晋其角，维用伐邑，厉吉无咎，贞吝。 象曰：“维用伐邑”，道未光也。”">​</a></h3><p>穷无所往，故曰角。居明之极，其施未光而应尚狭，持此以进，伐邑讨叛而已，危而幸吉以得无咎，然终吝道也。无可进而进不已，惟伐邑于内而可矣，如君子则知止也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
